// Validates the request. An LEI must pass the ISO 17442 check digits (ISO 7064 mod 97-10).
const b = $json.body || {};
const clean = v => (typeof v === 'string' ? v : (v == null ? '' : String(v))).trim();
const lei = clean(b.lei).toUpperCase().replace(/\s+/g, '');
const legalName = clean(b.legal_name).replace(/\s+/g, ' ').slice(0, 200);
const country = clean(b.country).toUpperCase();
const requestedBy = clean(b.requested_by).toLowerCase();
const purpose = clean(b.purpose).toLowerCase() || 'onboarding';
const errors = [];

const leiValid = s => {
  if (!/^[A-Z0-9]{18}[0-9]{2}$/.test(s)) return false;
  let rem = 0;
  for (const ch of s) {
    const d = /[A-Z]/.test(ch) ? String(ch.charCodeAt(0) - 55) : ch;
    for (const x of d) rem = (rem * 10 + Number(x)) % 97;
  }
  return rem === 1;
};

if (lei && !leiValid(lei)) errors.push('lei is not a valid ISO 17442 LEI (20 characters, check digits)');
if (!lei && legalName.length < 3) errors.push('send an lei, or a legal_name (3+ characters) with a country');
if (!lei && !/^[A-Z]{2}$/.test(country)) errors.push('country must be an ISO 3166 alpha-2 code when no lei is sent');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(requestedBy)) errors.push('requested_by must be an e-mail address');
if (!['onboarding', 'periodic_review', 'change_alert'].includes(purpose)) errors.push('purpose must be onboarding, periodic_review or change_alert');
const declared = {
  direct_parent: clean(b.declared_direct_parent).slice(0, 200),
  ultimate_parent: clean(b.declared_ultimate_parent).slice(0, 200),
  ubos: (Array.isArray(b.declared_ubos) ? b.declared_ubos : []).slice(0, 10).map(u => ({ name: clean(u && u.name).slice(0, 120), ownership_pct: Number(u && u.ownership_pct) || null }))
};
if (Array.isArray(b.declared_ubos) && declared.ubos.some(u => !u.name)) errors.push('each declared_ubos item needs a name');

return { json: {
  valid: errors.length === 0,
  errors,
  lei,
  legal_name: legalName,
  country,
  client_reference: clean(b.client_reference).slice(0, 100),
  requested_by: requestedBy,
  purpose,
  change_summary: clean(b.change_summary).slice(0, 2000),
  monitor: b.monitor === undefined ? true : b.monitor === true || b.monitor === 'true',
  declared,
  received_at: new Date().toISOString()
} };

// Picks exactly one GLEIF record for the request, or explains why not (422 or 503)
const req = $('Normalize and validate request').first().json;
const res = $json;
const status = Number(res.statusCode || 0);
if (status !== 200 || !Array.isArray(res.body?.data)) {
  return [{ json: { ...req, resolved: false, http_status: 503, problem: 'GLEIF registry did not answer (HTTP ' + (status || 'error') + '). Retry later.', candidates: [] } }];
}
const norm = s => String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, '');
const recs = res.body.data;
const brief = r => ({ lei: r.id, legal_name: r.attributes.entity.legalName.name, country: r.attributes.entity.legalAddress.country,
  entity_status: r.attributes.entity.status, registration_status: r.attributes.registration.status });
let pick = null;
if (req.lei) pick = recs.find(r => r.id === req.lei) || null;
else {
  const exact = recs.filter(r => [r.attributes.entity.legalName.name, ...(r.attributes.entity.otherNames || []).map(o => o.name)]
    .some(n => norm(n) === norm(req.legal_name)));
  if (exact.length === 1) pick = exact[0];
  else if (!exact.length && recs.length === 1) pick = recs[0];
}
if (!pick) {
  return [{ json: { ...req, resolved: false, http_status: 422,
    problem: req.lei ? 'This LEI is not in the GLEIF register.' : (recs.length ? 'Several GLEIF records match this name. Send the lei of the right one.' : 'No GLEIF record matches this name and country. Check the name or do this KYB check by hand.'),
    candidates: recs.slice(0, 5).map(brief) } }];
}
return [{ json: { ...req, resolved: true, lei: pick.id, legal_name: pick.attributes.entity.legalName.name,
  country: pick.attributes.entity.legalAddress.country, match_key: pick.id } }];

// EDIT ME: how long an accepted review can be reused, and when an open review counts as stale
const REUSE_DAYS = 30;
const OPEN_REVIEW_DAYS = 10;

const req = $('Pick the subject entity').first().json;
const now = Date.now();
const age = d => (now - Date.parse(d || 0)) / 86400000;
const rows = $input.all().map(i => i.json).filter(r => r.case_id);
const open = rows.find(r => r.status === 'open' && age(r.opened_at) < OPEN_REVIEW_DAYS);
// a change alert or a periodic review always needs a fresh look
const reusable = req.purpose === 'onboarding' && rows.find(r => r.status === 'closed' && r.decision === 'accepted' && age(r.decided_at) < REUSE_DAYS);
const action = open ? 'already_open' : reusable ? 'reuse_decision' : 'new_case';
const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
return [{ json: {
  ...req,
  action,
  existing_case: open || reusable || null,
  previous_reviews: rows.filter(r => r.status === 'closed').slice(0, 3).map(r => ({ case_id: r.case_id, decision: r.decision, risk_rating: r.risk_rating, decided_at: r.decided_at })),
  case_id: 'KYB-' + stamp + '-' + Math.random().toString(36).slice(2, 7).toUpperCase()
} }];

// Starts the ownership walk at the client's own LEI
const c = $('Check open reviews and reuse window').first().json;
return [{ json: { case_id: c.case_id, subject_lei: c.lei, current_lei: c.lei, depth: 0, hops: [], visited: [], more: true, stop_reason: '' } }];

// Records one level of the chain from three GLEIF answers and picks the next parent to fetch
const MAX_DEPTH = Number($('KYB settings').first().json.max_chain_depth) || 6;
const state = $('Next hop').item.json;
const rec = $('Get LEI record').item.json;
const rel = $('Get direct parent relationship').item.json;
const exc = $json;
const ok = r => Number(r && r.statusCode) === 200 && r.body && r.body.data;
const missing = r => Number(r && r.statusCode) === 404;

const hop = { depth: state.depth, lei: state.current_lei, data_gap: false };
if (ok(rec)) {
  const a = rec.body.data.attributes, e = a.entity, g = a.registration;
  Object.assign(hop, {
    legal_name: e.legalName.name,
    jurisdiction: e.jurisdiction || '',
    legal_country: e.legalAddress.country || '',
    hq_country: (e.headquartersAddress || {}).country || '',
    entity_status: e.status || '',
    category: e.category || '',
    legal_form: (e.legalForm || {}).id || '',
    legal_form_other: (e.legalForm || {}).other || '',
    created: e.creationDate || '',
    lei_status: g.status || '',
    lei_next_renewal: g.nextRenewalDate || '',
    lei_corroboration: g.corroborationLevel || '',
    previous_names: (e.otherNames || []).filter(o => /PREVIOUS/.test(o.type || '')).map(o => o.name).slice(0, 5),
    successor: (e.successorEntity || {}).lei || ''
  });
} else { hop.data_gap = true; hop.legal_name = '(record not available, HTTP ' + (rec && rec.statusCode) + ')'; }

let next = '';
if (ok(rel)) {
  const r = rel.body.data.attributes;
  hop.parent = {
    lei: r.relationship.endNode.id,
    relationship_status: r.relationship.status,
    record_status: r.registration.status,
    corroboration: r.registration.corroborationLevel,
    last_update: r.registration.lastUpdateDate
  };
  next = hop.parent.lei;
} else if (ok(exc)) {
  hop.parent_exception = exc.body.data.attributes.reason;
} else if (!(missing(rel) && missing(exc))) {
  hop.data_gap = true;
}
if (missing(rel) && missing(exc)) hop.parent_exception = 'NOT_REPORTED';

const visited = [...state.visited, state.current_lei];
let more = Boolean(next), stop = '';
if (next && visited.includes(next)) { more = false; stop = 'cycle'; }
else if (next && state.depth + 1 >= MAX_DEPTH) { more = false; stop = 'max_depth'; }
else if (!next) stop = hop.data_gap ? 'data_gap' : 'top_reached';

return [{ json: { ...state, hops: [...state.hops, hop], visited, current_lei: more ? next : '', depth: state.depth + 1, more, stop_reason: stop } }];

// EDIT ME: deterministic ownership risk flags. The AI can add context but never lower the rating below these flags.
const S = $('KYB settings').first().json;
const list = s => String(s || '').toUpperCase().split(/[\s,;]+/).filter(Boolean);
const BLACK = list(S.fatf_black_list), GREY = list(S.fatf_grey_list), EXTRA = list(S.extra_high_risk_countries);
const WITHHELD = ['NON_PUBLIC', 'BINDING_LEGAL_COMMITMENTS', 'LEGAL_OBSTACLES', 'DISCLOSURE_DETRIMENTAL', 'DETRIMENT_NOT_EXCLUDED', 'CONSENT_NOT_OBTAINED'];
const POINTS = { high: 3, medium: 2, low: 1, info: 0 };

const c = $('Check open reviews and reuse window').first().json;
const walk = $('Record hop and choose next').last().json;
const up = $('Get ultimate parent relationship').item.json;
const upx = $json;
const hops = walk.hops;
const subj = hops[0];
const flags = [];
const docs = new Set();
const flag = (code, severity, detail, doc) => { flags.push({ code, severity, detail }); if (doc) docs.add(doc); };
const yearsAgo = d => d ? (Date.now() - Date.parse(d)) / (365.25 * 86400000) : null;

// 1. registry status of every entity in the chain
for (const h of hops) {
  const who = h.depth === 0 ? 'Client' : 'Parent level ' + h.depth;
  if (h.data_gap) flag('REGISTRY_DATA_GAP', 'medium', who + ' ' + h.lei + ': GLEIF did not return complete data.', 'Commercial register extract for ' + h.lei);
  if (h.entity_status && h.entity_status !== 'ACTIVE') flag('ENTITY_NOT_ACTIVE', 'high', who + ' ' + h.legal_name + ' has entity status ' + h.entity_status + (h.successor ? ' (successor ' + h.successor + ')' : '') + '.', 'Evidence of the current legal status of ' + h.legal_name);
  if (['RETIRED', 'ANNULLED', 'MERGED', 'DUPLICATE'].includes(h.lei_status)) flag('LEI_RETIRED', 'high', who + ' LEI ' + h.lei + ' is ' + h.lei_status + '.');
  else if (h.lei_status === 'LAPSED') flag('LEI_LAPSED', h.depth === 0 ? 'medium' : 'low', who + ' LEI ' + h.lei + ' is lapsed (renewal was due ' + String(h.lei_next_renewal).slice(0, 10) + '); its data may be out of date.', h.depth === 0 ? 'Current commercial register extract (LEI data is lapsed)' : '');
  for (const cc of [...new Set([h.jurisdiction.slice(0, 2), h.legal_country, h.hq_country].filter(Boolean))]) {
    if (BLACK.includes(cc)) flag('FATF_CALL_FOR_ACTION', 'high', who + ' ' + h.legal_name + ' is linked to ' + cc + ', on the FATF call-for-action list (' + S.fatf_list_date + ').', 'Enhanced due diligence file and senior management approval');
    else if (GREY.includes(cc)) flag('FATF_INCREASED_MONITORING', 'medium', who + ' ' + h.legal_name + ' is linked to ' + cc + ', under FATF increased monitoring (' + S.fatf_list_date + ').', 'Source of funds and business rationale for the ' + cc + ' link');
    else if (EXTRA.includes(cc)) flag('INTERNAL_HIGH_RISK_COUNTRY', 'medium', who + ' ' + h.legal_name + ' is linked to ' + cc + ', on your internal high-risk list.', 'Business rationale for the ' + cc + ' link');
  }
  if (h.category === 'FUND' || /TRUST|FOUNDATION|STIFTUNG|FONDATION|FIDUCI/i.test(h.legal_name + ' ' + h.legal_form_other)) flag('COMPLEX_VEHICLE', 'medium', who + ' ' + h.legal_name + ' looks like a fund, trust or foundation; control may sit with trustees, settlors or beneficiaries.', 'Trust deed or foundation charter, with settlor, trustees, protector and beneficiaries');
  if (h.hq_country && h.legal_country && h.hq_country !== h.legal_country) flag('ADDRESS_COUNTRY_MISMATCH', 'low', who + ' ' + h.legal_name + ': legal address in ' + h.legal_country + ', headquarters in ' + h.hq_country + '.');
  if ((h.previous_names || []).length) flag('PREVIOUS_NAMES', 'info', who + ' ' + h.legal_name + ' was previously named: ' + h.previous_names.join('; ') + '.');
  if (h.parent) {
    if (h.parent.record_status === 'LAPSED') flag('PARENT_LINK_STALE', 'medium', who + ': the parent relationship record is lapsed (last update ' + String(h.parent.last_update).slice(0, 10) + ').', 'Up-to-date group structure chart');
    if (h.parent.corroboration === 'ENTITY_SUPPLIED_ONLY') flag('PARENT_LINK_NOT_CORROBORATED', 'low', who + ': the parent link is self-reported and not corroborated by the LEI issuer.');
    if (h.parent.relationship_status && h.parent.relationship_status !== 'ACTIVE') flag('PARENT_LINK_INACTIVE', 'medium', who + ': the parent relationship is ' + h.parent.relationship_status + '.', 'Up-to-date group structure chart');
  }
  const ex = h.parent_exception;
  if (ex === 'NATURAL_PERSONS') flag('OWNED_BY_NATURAL_PERSONS', 'low', who + ' ' + h.legal_name + ' reports that it is controlled by natural persons, who are not in GLEIF.', 'Beneficial owner declaration (persons with 25 % or more, or control by other means) with ID documents');
  else if (ex === 'NO_KNOWN_PERSON') flag('NO_KNOWN_CONTROLLING_PERSON', 'low', who + ' ' + h.legal_name + ' reports no controlling person (widely held or listed).', 'Evidence of listing or shareholder register; identify the senior managing official if no one holds 25 %');
  else if (WITHHELD.includes(ex)) flag('OWNERSHIP_WITHHELD', 'high', who + ' ' + h.legal_name + ' does not disclose its parent in GLEIF (reason ' + ex + ').', 'Shareholder register and group structure chart up to the beneficial owners');
  else if (ex === 'NO_LEI') flag('PARENT_WITHOUT_LEI', 'medium', who + ' ' + h.legal_name + ' has a parent that has no LEI, so the chain stops here.', 'Register extract of the parent company and its owners');
  else if (ex === 'NOT_REPORTED') flag('PARENT_NOT_REPORTED', 'medium', who + ' ' + h.legal_name + ' has filed neither a parent nor a reporting exception.', 'Shareholder register and group structure chart');
}
if (subj && !subj.data_gap) {
  const age = yearsAgo(subj.created);
  if (age !== null && age < 1) flag('RECENTLY_INCORPORATED', 'low', 'The client was incorporated ' + String(subj.created).slice(0, 10) + ', less than a year ago.', 'Business plan and expected account activity');
}

// 2. chain shape
const juris = [...new Set(hops.map(h => h.legal_country).filter(Boolean))];
if (juris.length >= 3) flag('MULTI_JURISDICTION_CHAIN', 'medium', 'The chain crosses ' + juris.length + ' countries: ' + juris.join(' > ') + '.', 'Group structure chart explaining each intermediate holding');
if (walk.stop_reason === 'cycle') flag('CIRCULAR_OWNERSHIP', 'high', 'The parent links form a loop; ownership cannot be resolved from GLEIF.', 'Group structure chart up to the beneficial owners');
if (walk.stop_reason === 'max_depth') flag('CHAIN_TRUNCATED', 'medium', 'The chain is deeper than ' + hops.length + ' levels; the walk stopped.', 'Group structure chart above level ' + hops.length);
const top = hops[hops.length - 1];
let ultimate = { lei: '', exception: '' };
if (Number(up.statusCode) === 200 && up.body && up.body.data) ultimate.lei = up.body.data.attributes.relationship.endNode.id;
else if (Number(upx.statusCode) === 200 && upx.body && upx.body.data) ultimate.exception = upx.body.data.attributes.reason;
const chainTop = hops.length > 1 ? top.lei : '';
if (ultimate.lei && chainTop && ultimate.lei !== chainTop && walk.stop_reason === 'top_reached') flag('ULTIMATE_PARENT_MISMATCH', 'medium', 'GLEIF names ' + ultimate.lei + ' as ultimate parent, but the direct-parent chain ends at ' + chainTop + '.', 'Group structure chart reconciling both');
if (ultimate.lei && !chainTop) flag('ULTIMATE_PARENT_WITHOUT_DIRECT', 'medium', 'GLEIF names an ultimate parent ' + ultimate.lei + ' but no direct parent.', 'Group structure chart');

// 3. compare with what the client declared
const LEGAL = /\b(AG|SA|S A|GMBH|LTD|LIMITED|PLC|INC|LLC|LLP|SARL|SAS|BV|NV|SPA|SRL|AB|AS|OY|KG|SE|CORP|CORPORATION|COMPANY|CO|THE)\b/g;
const tok = s => new Set(String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9 ]+/g, ' ').replace(LEGAL, ' ').split(/\s+/).filter(Boolean));
const similar = (a, b) => { const A = tok(a), B = tok(b); if (!A.size || !B.size) return 0; let i = 0; for (const x of A) if (B.has(x)) i++; return 2 * i / (A.size + B.size); };   // Dice similarity of name tokens without legal forms
const d = c.declared || {};
const parentHop = hops[1];
const discrepancies = [];
if (d.direct_parent) {
  if (!parentHop) discrepancies.push('Client declared direct parent "' + d.direct_parent + '", GLEIF reports none (' + (subj.parent_exception || 'no parent') + ').');
  else if (similar(d.direct_parent, parentHop.legal_name) < 0.6) discrepancies.push('Client declared direct parent "' + d.direct_parent + '", GLEIF says ' + parentHop.legal_name + ' (' + parentHop.lei + ').');
} else if (parentHop) flag('PARENT_NOT_DECLARED', 'low', 'The client did not declare a parent; GLEIF reports ' + parentHop.legal_name + '.');
if (d.ultimate_parent && hops.length > 1 && similar(d.ultimate_parent, top.legal_name) < 0.6) discrepancies.push('Client declared ultimate parent "' + d.ultimate_parent + '", the GLEIF chain ends at ' + top.legal_name + ' (' + top.lei + ').');
if (discrepancies.length) flag('DECLARATION_DISCREPANCY', 'high', discrepancies.join(' '), 'Written explanation of the difference between the declaration and the LEI register');
const ubos = d.ubos || [];
const pct = ubos.reduce((s, u) => s + (u.ownership_pct || 0), 0);
if (pct > 100.5) flag('UBO_PERCENTAGES_INCONSISTENT', 'medium', 'Declared beneficial owners add up to ' + pct + ' %.', 'Corrected beneficial owner declaration');
const needsUbo = hops.some(h => h.parent_exception === 'NATURAL_PERSONS');
if (needsUbo && !ubos.length) docs.add('Beneficial owner declaration (persons with 25 % or more, or control by other means) with ID documents');
if (ubos.length && !ubos.some(u => (u.ownership_pct || 0) >= 25)) flag('NO_UBO_OVER_25', 'low', 'No declared beneficial owner holds 25 % or more.', 'Name of the senior managing official and evidence of control');
if (c.purpose === 'change_alert' && c.change_summary) flag('REGISTRY_CHANGE_DETECTED', 'medium', 'Weekly monitoring found: ' + c.change_summary);

// 4. rating floor
const points = flags.reduce((s, f) => s + POINTS[f.severity], 0);
const floor = flags.some(f => f.severity === 'high') || points >= 7 ? 'high' : points >= 3 ? 'medium' : 'low';
const fp = [subj.legal_name, subj.jurisdiction, subj.legal_country, subj.entity_status, subj.lei_status,
  subj.parent ? subj.parent.lei : 'none', ultimate.lei || 'none'].join('|');
return [{ json: {
  case_id: c.case_id, lei: c.lei, legal_name: subj.legal_name || c.legal_name, client_reference: c.client_reference,
  requested_by: c.requested_by, purpose: c.purpose, change_summary: c.change_summary, monitor: c.monitor, declared: d,
  previous_reviews: c.previous_reviews || [],
  hops, chain_leis: hops.map(h => h.lei).join(' > '), stop_reason: walk.stop_reason, ultimate_parent: ultimate,
  flags, rating_floor: floor, flag_points: points, suggested_documents: [...docs].filter(Boolean),
  fingerprint: fp, baseline: { legal_name: subj.legal_name, jurisdiction: subj.jurisdiction, legal_country: subj.legal_country,
    entity_status: subj.entity_status, lei_status: subj.lei_status, direct_parent: subj.parent ? subj.parent.lei : 'none', ultimate_parent: ultimate.lei || 'none' },
  fatf_list_date: S.fatf_list_date
} }];

