// The AI agent failed (outage, timeout or invalid answer): build a rule-based memo so the review still happens
const a = $('Assess ownership risk flags').first().json;
const top = a.hops[a.hops.length - 1];
return [{ json: { ai_failed: true, ai_error: String($json.error?.message || $json.error || 'agent error').slice(0, 300), output: {
  risk_rating: a.rating_floor,
  confidence: 0,
  ownership_summary: 'AI analyst unavailable. Rule-based summary: ' + a.hops.length + ' level(s) found in GLEIF, from ' + a.legal_name
    + (a.hops.length > 1 ? ' up to ' + top.legal_name + ' (' + top.legal_country + ')' : '') + '. ' + a.flags.length + ' flag(s) raised.',
  flag_assessments: a.flags.map(f => ({ code: f.code, assessment: 'needs_review', comment: f.detail })),
  additional_concerns: [],
  documents_to_request: a.suggested_documents.map(d => ({ document: d, reason: 'rule-based flag' })),
  questions_for_reviewer: ['The AI analyst did not answer. Review the flags and the chain yourself.'],
  answer_to_reviewer: ''
} } }];

// EDIT ME: review policy. The AI can raise the rating but never lower it below the rule-based floor.
const MAX_FOLLOW_UPS = 2;
const ORDER = ['low', 'medium', 'high'];

const a = $('Assess ownership risk flags').first().json;
const followUp = $('Prepare follow-up for the analyst').isExecuted ? $('Prepare follow-up for the analyst').last().json : null;
const round = followUp ? followUp.round : 0;
const qa = followUp ? [...(followUp.qa_history || []), { question: followUp.follow_up_question, answer: '' }] : [];
const ai = $json.output || {};
const aiFailed = Boolean($json.ai_failed);
if (qa.length) qa[qa.length - 1].answer = String(ai.answer_to_reviewer || '').slice(0, 1500);
const aiRating = ORDER.includes(ai.risk_rating) ? ai.risk_rating : 'high';
const rating = ORDER[Math.max(ORDER.indexOf(aiRating), ORDER.indexOf(a.rating_floor))];
const raisedByAi = ORDER.indexOf(aiRating) > ORDER.indexOf(a.rating_floor);

const seen = new Set();
const documents = [...(ai.documents_to_request || []).map(d => d.document + (d.reason ? ' (' + d.reason + ')' : '')), ...a.suggested_documents]
  .filter(d => { const k = String(d).toLowerCase().slice(0, 40); if (!d || seen.has(k)) return false; seen.add(k); return true; }).slice(0, 12);

const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const color = { high: '#b00020', medium: '#b26a00', low: '#2e7d32', info: '#555' };
const chain = a.hops.map(h => '<tr><td>' + h.depth + '</td><td><b>' + esc(h.legal_name) + '</b><br>' + esc(h.lei) + '</td><td>' + esc(h.legal_country) + (h.hq_country && h.hq_country !== h.legal_country ? ' / HQ ' + esc(h.hq_country) : '')
  + '</td><td>' + esc(h.entity_status) + ' / LEI ' + esc(h.lei_status) + '</td><td>' + (h.parent ? 'parent ' + esc(h.parent.lei) + ' (' + esc(h.parent.record_status) + ', ' + esc(h.parent.corroboration) + ')' : 'exception: ' + esc(h.parent_exception || 'n/a')) + '</td></tr>').join('');
const flags = a.flags.map(f => '<li><b style="color:' + color[f.severity] + '">' + f.severity.toUpperCase() + ' ' + esc(f.code) + '</b>: ' + esc(f.detail) + '</li>').join('') || '<li>No rule-based flags.</li>';
const aiNotes = (ai.flag_assessments || []).map(f => '<li>' + esc(f.code) + ': <i>' + esc(f.assessment) + '</i> ' + esc(f.comment) + '</li>').join('');
const html = '<h3>KYB ownership review ' + esc(a.case_id) + ': ' + esc(a.legal_name) + '</h3>'
  + '<p><b>Risk rating: <span style="color:' + color[rating] + '">' + rating.toUpperCase() + '</span></b> (rules: ' + a.rating_floor + ', AI: ' + (aiFailed ? 'unavailable' : aiRating) + ') | purpose: ' + esc(a.purpose) + ' | client ref: ' + esc(a.client_reference || 'n/a') + '</p>'
  + (a.change_summary ? '<p><b>Change found by monitoring:</b> ' + esc(a.change_summary) + '</p>' : '')
  + '<p><b>AI ownership memo:</b> ' + esc(ai.ownership_summary) + '</p>'
  + (ai.answer_to_reviewer ? '<p><b>Answer to your question:</b> ' + esc(ai.answer_to_reviewer) + '</p>' : '')
  + '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Level</th><th>Entity</th><th>Country</th><th>Status</th><th>Parent link</th></tr>' + chain + '</table>'
  + '<p>Ultimate parent in GLEIF: ' + esc(a.ultimate_parent.lei || a.ultimate_parent.exception || 'none reported') + '</p>'
  + '<h4>Flags</h4><ul>' + flags + '</ul>'
  + (aiNotes ? '<h4>AI notes on the flags</h4><ul>' + aiNotes + '</ul>' : '')
  + ((ai.additional_concerns || []).length ? '<h4>Other concerns</h4><ul>' + ai.additional_concerns.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '')
  + '<h4>Documents to request</h4><ul>' + (documents.map(x => '<li>' + esc(x) + '</li>').join('') || '<li>None</li>') + '</ul>'
  + ((ai.questions_for_reviewer || []).length ? '<h4>Questions for you</h4><ul>' + ai.questions_for_reviewer.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '')
  + '<p><i>GLEIF shows accounting-consolidation parents, not beneficial owners. FATF lists dated ' + esc(a.fatf_list_date) + '. Decision support only, not legal advice.</i></p>';

return [{ json: {
  ...a,
  risk_rating: rating,
  ai_rating: aiFailed ? '' : aiRating,
  raised_by_ai: raisedByAi,
  ai_failed: aiFailed,
  ai_summary: String(ai.ownership_summary || '').slice(0, 2000),
  ai_answer: String(ai.answer_to_reviewer || ''),
  ai_assessment: ai,
  documents,
  senior_approval_required: rating === 'high',
  round,
  qa_history: qa,
  can_follow_up: round < MAX_FOLLOW_UPS,
  review_html: html
} }];

// Sends the reviewer's question back to the AI analyst, together with its previous memo and earlier Q&A
const p = $('Apply review policy').last().json;
return [{ json: {
  ...p,
  round: p.round + 1,
  follow_up_question: String($json['Follow-up question'] || '').slice(0, 1000) || 'Please explain your rating in more detail.',
  asked_by: $json['Reviewer name'] || ''
} }];

