// Four-eyes rule for high-risk structures: the senior approver must approve from their own mailbox,
// and cannot be the reviewer who accepted
const first = $('Wait for reviewer decision').last().json;
const settings = $('KYB settings').first().json;
const norm = s => String(s || '').trim().toLowerCase();
const answered = typeof $json.data?.approved === 'boolean';
const approved = $json.data?.approved === true;
const samePerson = norm(first['Reviewer e-mail']) === norm(settings.senior_approver_email);
return [{ json: {
  senior_checked: true,
  decision: answered && approved && !samePerson ? 'accepted' : 'escalated',
  reviewer: (first['Reviewer name'] || '') + ' <' + norm(first['Reviewer e-mail']) + '>',
  rationale: first['Rationale'] || '',
  senior_approver: answered ? settings.senior_approver_email : '',
  escalation_reason: samePerson ? 'four-eyes rule: the reviewer is the senior approver'
    : !answered ? 'senior approval timed out'
    : approved ? '' : 'senior approver rejected the high-risk structure'
} }];

// Builds one audit record, whatever path the review took
const p = $('Apply review policy').last().json;
const j = $json;
const who = x => x['Reviewer name'] ? x['Reviewer name'] + ' <' + String(x['Reviewer e-mail'] || '').toLowerCase() + '>' : '';
const choice = String(j['Decision'] || '');
let decision, reviewer = '', senior = '', rationale = '', reason = '', documents = [];
if (j.senior_checked) { decision = j.decision; reviewer = j.reviewer; senior = j.senior_approver; rationale = j.rationale; reason = j.escalation_reason; }
else if (choice.startsWith('Accept')) { decision = 'accepted'; reviewer = who(j); rationale = j['Rationale']; }
else if (choice.startsWith('Request')) {
  decision = 'documents_requested'; reviewer = who(j); rationale = j['Rationale'];
  documents = [...p.documents, ...String(j['Extra documents to request'] || '').split(/\n+/).map(s => s.trim()).filter(Boolean)];
}
else {
  decision = 'escalated'; reviewer = who(j); rationale = j['Rationale'] || '';
  reason = !choice ? 'no reviewer decision in time' : choice.startsWith('Ask') ? 'follow-up limit reached' : 'reviewer escalated the structure';
}
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const label = decision.replace(/_/g, ' ');
const requesterHtml = '<p>Review <b>' + esc(p.case_id) + '</b> (' + esc(p.lei) + ') is closed with the result <b>' + label + '</b>, risk rating ' + p.risk_rating + '.</p>'
  + (decision === 'documents_requested' ? '<p>Please ask the client for:</p><ul>' + documents.map(d => '<li>' + esc(d) + '</li>').join('') + '</ul><p>Send a new request with purpose periodic_review when they arrive.</p>'
    : decision === 'escalated' ? '<p>Do not onboard or extend this relationship until compliance contacts you.</p>'
    : '<p>No further action is needed.' + (p.monitor ? ' Ownership changes in GLEIF will be checked every week.' : '') + '</p>')
  + '<p><i>Based on the public GLEIF register; consolidation parents are not beneficial owners.</i></p>';
const officerHtml = '<p><b>Reason:</b> ' + esc(reason) + '<br><b>Reviewer:</b> ' + esc(reviewer || 'none') + '<br><b>Rationale:</b> ' + esc(rationale || 'none') + '</p>'
  + p.review_html + '<p>Keep the onboarding or the relationship on hold until this review is resolved.</p>';
return [{ json: {
  case_id: p.case_id, lei: p.lei, legal_name: p.legal_name, client_reference: p.client_reference, requested_by: p.requested_by,
  status: 'closed', decision, escalated: decision === 'escalated',
  monitor: p.monitor && decision === 'accepted',
  risk_rating: p.risk_rating, rating_floor: p.rating_floor, ai_rating: p.ai_rating,
  flag_codes: p.flags.map(f => f.code).join(', '), chain_leis: p.chain_leis, ultimate_parent: p.ultimate_parent.lei || p.ultimate_parent.exception || '',
  ai_summary: p.ai_summary, reviewer, senior_approver: senior, rationale: String(rationale || '').slice(0, 2000),
  escalation_reason: reason, documents_requested: documents.join('\n'), rounds: p.round,
  fingerprint: p.fingerprint, baseline_json: JSON.stringify(p.baseline),
  decided_at: new Date().toISOString(), requester_html: requesterHtml, officer_html: officerHtml
} }];

// Compares each monitored client's current GLEIF data with the baseline saved at its last accepted review
const clients = $('Get monitored clients').all();
const recs = $('Get current LEI record').all();
const dps = $('Get current direct parent').all();
const ups = $input.all();
const ok = r => Number(r && r.statusCode) === 200 && r.body && r.body.data;
const out = [];
clients.forEach((c, i) => {
  const b = c.json, rec = recs[i] && recs[i].json, dp = dps[i] && dps[i].json, up = ups[i] && ups[i].json;
  const now = new Date().toISOString();
  const failed = !ok(rec) || ![200, 404].includes(Number(dp && dp.statusCode)) || ![200, 404].includes(Number(up && up.statusCode));
  if (failed) { out.push({ json: { id: b.id, lei: b.lei, changed: false, last_checked: now, last_result: 'gleif_unavailable', alerted_fingerprint: b.alerted_fingerprint || '' } }); return; }
  const e = rec.body.data.attributes.entity, g = rec.body.data.attributes.registration;
  const cur = { legal_name: e.legalName.name, jurisdiction: e.jurisdiction || '', legal_country: e.legalAddress.country || '',
    entity_status: e.status || '', lei_status: g.status || '',
    direct_parent: ok(dp) ? dp.body.data.attributes.relationship.endNode.id : 'none',
    ultimate_parent: ok(up) ? up.body.data.attributes.relationship.endNode.id : 'none' };
  const fp = [cur.legal_name, cur.jurisdiction, cur.legal_country, cur.entity_status, cur.lei_status, cur.direct_parent, cur.ultimate_parent].join('|');
  let base = {}; try { base = JSON.parse(b.baseline_json || '{}'); } catch (err) {}
  const changes = Object.keys(cur).filter(k => String(base[k] ?? '') !== String(cur[k])).map(k => k + ': ' + (base[k] ?? 'n/a') + ' -> ' + cur[k]);
  const changed = fp !== b.fingerprint && fp !== b.alerted_fingerprint;   // alert once per new state
  out.push({ json: { id: b.id, lei: b.lei, client_reference: b.client_reference, requested_by: b.requested_by, legal_name: cur.legal_name,
    changed, change_summary: changes.join('; '), last_checked: now,
    last_result: fp === b.fingerprint ? 'unchanged' : changed ? 'change_alerted' : 'change_already_alerted',
    alerted_fingerprint: changed ? fp : (b.alerted_fingerprint || '') } });
});
return out;
